<script setup lang="ts">
definePageMeta({ layout: 'dashboard' })
useSeoMeta({ title: 'Administração do FLUXO', robots: 'noindex, nofollow' })
const auth = useAuth(); const config = useRuntimeConfig().public
const providers = ref<any[]>([]); const tenants = ref<any[]>([]); const loading = ref(true); const notice = ref(''); const error = ref('')
const provider = reactive({ provider_key: '', display_name: '', channel: 'whatsapp_waba', credential_reference: '' })
const invitation = reactive({ name: '', email: '', tenant_name: '' })
async function request(path: string, init: RequestInit = {}) {
  const client = auth.client(); const { data } = await client!.auth.getSession()
  const response = await fetch(String(config.apiBase).replace(/\/$/, '') + path, { ...init, headers: { Authorization: `Bearer ${data.session!.access_token}`, ...(init.body ? { 'Content-Type': 'application/json' } : {}) } })
  const payload = await response.json().catch(() => null)
  if (!response.ok) throw new Error(payload?.error?.message || 'Não foi possível concluir esta ação.')
  return payload
}
async function load() { loading.value = true; error.value = ''; try { const [p, t] = await Promise.all([request('/v1/admin/providers'), request('/v1/admin/tenants')]); providers.value = p.providers; tenants.value = t.tenants } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Acesso administrativo indisponível.' } finally { loading.value = false } }
async function addProvider() { try { await request('/v1/admin/providers', { method: 'POST', body: JSON.stringify(provider) }); notice.value = 'Provedor registrado como pendente. Configure a credencial correspondente somente no ambiente privado da VPS.'; Object.assign(provider, { provider_key: '', display_name: '', channel: 'whatsapp_waba', credential_reference: '' }); await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Não foi possível registrar o provedor.' } }
async function invite() { try { await request('/v1/admin/users', { method: 'POST', body: JSON.stringify(invitation) }); notice.value = 'Convite criado e tenant inicial provisionado para o novo usuário.'; Object.assign(invitation, { name: '', email: '', tenant_name: '' }); await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Não foi possível criar o convite.' } }
onMounted(load)
</script>
<template><div><header class="page-heading"><div><p class="eyebrow">SUPERADMIN · FLUXO</p><h1>Plataforma, tenants e provedores.</h1><p>Esta área opera a camada global. Ela não revela segredos de canais nem dados internos dos tenants.</p></div></header><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="live-notice" role="status">{{ notice }}</p><div v-if="loading" class="empty-state">Carregando a administração…</div><template v-else><section class="admin-grid"><form class="panel admin-form" @submit.prevent="invite"><h2>Cadastrar usuário</h2><p>O Supabase envia um convite seguro e cria um tenant isolado.</p><div class="field"><label>Nome</label><input v-model="invitation.name" required maxlength="120"></div><div class="field"><label>E-mail</label><input v-model="invitation.email" type="email" required maxlength="254"></div><div class="field"><label>Nome do tenant</label><input v-model="invitation.tenant_name" required maxlength="120" placeholder="Empresa da pessoa"></div><button class="button button-primary">Enviar convite</button></form><form class="panel admin-form" @submit.prevent="addProvider"><h2>Cadastrar provedor global</h2><p>A referência aponta para um segredo privado da VPS; nunca informe o segredo aqui.</p><div class="field"><label>Chave interna</label><input v-model="provider.provider_key" pattern="[a-z0-9][a-z0-9_-]{2,62}" required placeholder="meta_waba_principal"></div><div class="field"><label>Nome visível</label><input v-model="provider.display_name" required maxlength="120" placeholder="WhatsApp Business principal"></div><div class="field"><label>Canal</label><select v-model="provider.channel"><option value="whatsapp_waba">WhatsApp Business / WABA</option><option value="email_smtp">E-mail SMTP</option></select></div><div class="field"><label>Referência de credencial na VPS</label><input v-model="provider.credential_reference" pattern="[A-Z][A-Z0-9_]{2,127}" required placeholder="META_WABA_PRIMARY"></div><button class="button button-primary">Registrar provedor</button></form></section><section class="panel admin-list"><h2>Provedores globais</h2><p v-if="!providers.length">Nenhum provedor cadastrado.</p><ul v-else><li v-for="item in providers" :key="item.id"><strong>{{ item.display_name }}</strong><span>{{ item.channel }} · {{ item.status }} · {{ item.credential_reference }}</span></li></ul></section><section class="panel admin-list"><h2>Tenants cadastrados</h2><p v-if="!tenants.length">Ainda não há tenants.</p><ul v-else><li v-for="item in tenants" :key="item.id"><strong>{{ item.name }}</strong><span>{{ item.id }}</span></li></ul></section></template></div></template>
